package com.anthem.cartman.appimages.entity;

import jakarta.persistence.Basic;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Lob;
import jakarta.persistence.Table;

import org.hibernate.annotations.DynamicUpdate;

/**
 * Module 11 — one stored page of a scanned paper application, in {@code TM_App_Images}.
 *
 * <p>The key is generated by the database, as every other key in this schema is
 * ({@code TM_UW_Actions.UW_ID}, {@code TM_App_Floating_Note.FN_ID} and the rest are all identity
 * columns). That is precisely why CARTMAN cannot know the key it just created and asks for
 * {@code Max(APG_ID)} instead — the mistake behind A65. Here the insert returns its own key.
 *
 * <p>The document is a lazy {@code @Lob}: the list screen reads five short columns for every row and
 * must never drag a PDF per row across with them.
 */
@Entity
@Table(name = "TM_App_Images")
@DynamicUpdate
public class AppImage {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "APG_ID")
    private Integer id;

    @Column(name = "APG_State", length = 2)
    private String state;

    @Column(name = "APG_Year", length = 8)
    private String year;

    @Column(name = "APG_Version", length = 32)
    private String version;

    @Column(name = "APG_Page_Number", length = 8)
    private String pageNumber;

    @Lob
    @Basic(fetch = FetchType.LAZY)
    @Column(name = "APG_Page")
    private byte[] page;

    public Integer getId() {
        return id;
    }

    public String getState() {
        return state;
    }

    public void setState(String state) {
        this.state = state;
    }

    public String getYear() {
        return year;
    }

    public void setYear(String year) {
        this.year = year;
    }

    public String getVersion() {
        return version;
    }

    public void setVersion(String version) {
        this.version = version;
    }

    public String getPageNumber() {
        return pageNumber;
    }

    public void setPageNumber(String pageNumber) {
        this.pageNumber = pageNumber;
    }

    public byte[] getPage() {
        return page;
    }

    public void setPage(byte[] page) {
        this.page = page;
    }
}
